前言 本文记录在 Vue3 项目中集成高德地图（AMAP），并调用搜索地点服务。
设置地图与搜索服务 下面示例包含地图初始化与请求“医院/诊所”数据的逻辑。
import axios from &#34;axios&#34;; import { ref, onMounted, onUnmounted } from &#34;vue&#34;; import AMapLoader from &#34;@amap/amap-jsapi-loader&#34;; let map = null; const loading = ref(false); const getHospital = async () =&gt; { loading.value = true; let hospitalList = []; let clinicList = []; let page = 1; while (true) { const { data: res } = await axios.get( `https://restapi.amap.com/v3/place/text?keywords=医院&amp;city=430100&amp;offset=50&amp;page=${page}&amp;key=1c75af4f449f301bacd944e0a9855dae&amp;extensions=all` ); hospitalList = hospitalList.concat(res.pois); page++; if (res.pois.length &lt; 50) { break; } } page = 1; while (true) { const { data: res } = await axios.get( `https://restapi.amap.com/v3/place/text?keywords=诊所&amp;city=430100&amp;offset=50&amp;page=${page}&amp;key=1c75af4f449f301bacd944e0a9855dae&amp;extensions=all` ); clinicList = clinicList.concat(res.pois); page++; if (res.pois.length &lt; 50) { break; } } loading.value = false; return [hospitalList, clinicList]; }; const initMap = async () =&gt; { const AMap = await AMapLoader.load({ key: &#34;25304e4dd58635d7b98eaafe0f58e786&#34;, // 申请好的 Web 端开发者 Key version: &#34;2.0&#34;, plugins: [], }); map = new AMap.Map(&#34;container&#34;, { viewMode: &#34;3D&#34;, zoom: 11, center: [116.397428, 39.90923], }); // await getHospital(); }; onMounted(async () =&gt; { await initMap(); }); onUnmounted(() =&gt; { map?.destroy(); }); 页面结构与样式 &lt;div id=&#34;container&#34;&gt;&lt;/div&gt; #container { width: 100%; height: 100%; }
